<body>
<main id="app"><h1>Workboard</h1><div id="content"></div></main>
<script>
const content = document.querySelector('#content');
const escapePath = id => `/projects/${encodeURIComponent(id)}`;
async function projects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}
function showList() {
  document.querySelector('h1').textContent = 'Workboard';
  content.innerHTML = '<form id="create-form"><div class="field"><label for="project-name">Project name</label><input id="project-name" name="name" type="text"></div><button type="submit">Create project</button></form><div id="alert" role="alert" aria-live="polite"></div><section id="project-list" aria-label="Projects"></section>';
  const form = document.querySelector('#create-form');
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = new FormData(form).get('name').trim();
    const alert = document.querySelector('#alert');
    if (!name) { alert.textContent = 'Project name is required'; return; }
    const response = await fetch('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
    if (!response.ok) { alert.textContent = 'Could not create project'; return; }
    history.pushState({}, '', '/');
    await renderList();
  });
  renderList();
}
async function renderList() {
  const list = document.querySelector('#project-list');
  if (!list) return;
  try {
    const items = await projects();
    list.replaceChildren();
    for (const project of items) {
      const row = document.createElement('div'); row.className = 'row'; row.dataset.testid = 'project-row';
      const name = document.createElement('span'); name.className = 'row-name'; name.textContent = project.name;
      const button = document.createElement('button'); button.type = 'button'; button.textContent = 'Open project';
      button.addEventListener('click', () => { history.pushState({}, '', escapePath(project.id)); render(); });
      row.append(name, button); list.append(row);
    }
  } catch { list.textContent = 'Could not load projects'; }
}
async function render() {
  const match = location.pathname.match(/^\/projects\/([^/]+)$/);
  if (!match) { showList(); return; }
  let project;
  try { project = (await projects()).find(item => item.id === decodeURIComponent(match[1])); } catch {}
  document.querySelector('h1').textContent = project ? project.name : 'Project not found';
  content.replaceChildren();
  const back = document.createElement('button'); back.type = 'button'; back.textContent = 'Projects';
  back.addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
  content.append(back);
}
window.addEventListener('popstate', render);
render();
</script>
